class _Edges(list):
    def __iter__(self):
        _SCANS[self.owner] = _SCANS.get(self.owner, 0) + 1
        return list.__iter__(self)


_SCANS = {}


def _edges(owner, items):
    e = _Edges(items)
    e.owner = owner
    return e


def hub_scans(k):
    """dist to the hub h, and how many times h's edge list was read"""
    _SCANS.clear()
    adj = {"s": _edges("s", [("c1", 1)])}
    for i in range(1, k + 1):
        nxt = [("c%d" % (i + 1), 1)] if i < k else []
        adj["c%d" % i] = _edges("c%d" % i, nxt + [("h", 2 * k - 2 * i)])
    adj["h"] = _edges("h", [("t%d" % j, 1) for j in range(k)])
    for j in range(k):
        adj["t%d" % j] = _edges("t%d" % j, [])
    dist = dijkstra(adj, "s")
    return dist["h"], _SCANS.get("h", 0)

