import heapq
import math


def slowest_arrival(links, centres, src):
    adj = {c: [] for c in centres}
    for a, b, ms in links:
        adj[a].append((b, ms))
    dist = {c: math.inf for c in centres}
    dist[src] = 0
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, ms in adj[u]:
            if d + ms < dist[v]:
                dist[v] = d + ms
                heapq.heappush(heap, (d + ms, v))
    worst = max(dist.values())
    return -1 if worst == math.inf else worst
